INSERT INTO sources(id,title,url,publisher,publication_date,reuse_license,attribution) VALUES('src-z-anatomy-bodyparts3d','Z-Anatomy & BodyParts3D Open 3D Anatomical Atlas','https://www.z-anatomy.com/','Z-Anatomy / DBCLS BodyParts3D','2024','CC-BY-SA-4.0 / CC-BY-SA-2.1-JP','Z-Anatomy (G.ael Kerchenbaum) derived from BodyParts3D (Database Center for Life Science, Japan).') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-cardiovascular','الجهاز القلبي الوعائي','Cardiovascular System','Systema cardiovasculare','شبكة الضخ الهيدروديناميكية المغلقة المكونة من القلب (Cor) والأوعية الدموية الشريانية والوريدية والشعيرات الدقيقة المسؤولة عن تروية الأنسجة بالأكسجين والمغذيات ونقل الدواء.','Closed hydrodynamic pumping network composed of the heart (Cor) and arterial, capillary, and venous vessels responsible for tissue perfusion and systemic drug distribution.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,TRUE,'يرتبط وثيقاً بالجهاز التنفسي عبر الدورة الرئوية لتبادل الغازات، وبالجهاز الكلوي عبر محور الرينين-أنجيوتنسين-ألدوستيرون (RAAS) لتنظيم حجم الدم وضغطه، وبالجهاز العصبي الذاتي لتعديل سرعة القلب ونتاجه.','Tightly coupled with the respiratory system via pulmonary circulation, with the renal system via the RAAS axis for volume/pressure regulation, and with the autonomic nervous system for chronotropic/inotropic modulation.','["ACE Inhibitors","Beta-1 Selective Blockers","Calcium Channel Blockers","Loop Diuretics","Antiarrhythmics"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-respiratory','الجهاز التنفسي','Respiratory System','Systema respiratorium','المنظومة التشريحية المسؤولة عن التهوية الرئوية وتبادل الأكسجين وثاني أكسيد الكربون عبر الحاجز السنخي الشعري والمساهمة في التوازن الحمضي القاعدي.','Anatomical system governing pulmonary ventilation, alveolar-capillary gas exchange, and respiratory acid-base homeostasis.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,TRUE,'يتكامل مع البطين الأيمن والأذين الأيسر عبر الشريان والأوردة الرئوية، ويتشارك مع الكليتين في ضبط باهاء الدم (pH) عبر معادلة البيكربونات وحمض الكربونيك.','Integrates with the right ventricle and left atrium via pulmonary vasculature and collaborates with the kidneys to regulate arterial blood pH via bicarbonate buffering.','["Short-Acting Beta-2 Agonists (SABA)","Inhaled Corticosteroids (ICS)","Long-Acting Muscarinic Antagonists (LAMA)","Leukotriene Receptor Antagonists"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-digestive','الجهاز الهضمي والكبدي','Digestive & Hepatobiliary System','Systema digestorium','القناة الهضمية والأعضاء الملحقة (الكبد والبنكرياس والمرارة) المسؤولة عن الهضم والامتصاص المعوي والتمثيل الغذائي الكبدي الأولي للأدوية (First-Pass Metabolism).','Gastrointestinal tract and accessory organs (liver, pancreas, gallbladder) governing digestion, intestinal absorption, and hepatic first-pass drug metabolism.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,TRUE,'ينقل الدم الوريدي من الأمعاء عبر الوريد البابي الكبدي (Vena portae hepatis) إلى الكبد لمعالجة المغذيات والأدوية قبل وصولها إلى الدورة الجهازية، ويخضع لتنظيم العصب المبهم (Nervus vagus).','Delivers splanchnic venous blood via the hepatic portal vein to the liver before systemic circulation and is regulated by the enteric nervous system and vagus nerve.','["Proton Pump Inhibitors (PPIs)","H2 Receptor Antagonists","Mucosal Cytoprotective Agents","Antiemetics"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-renal','الجهاز البولي والكلوي','Urinary & Renal System','Systema urinarium','منظومة الترشيح الكبيبي وإعادة الامتصاص والإفراز الأنبوبي في النفرونات الكلوية لضبط توازن السوائل والشوارد وإطراح المستقلبات الدوائية.','Glomerular filtration and tubular reabsorption/secretion system maintaining fluid-electrolyte balance and renal drug clearance.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,TRUE,'يتحكم في ضغط الدم الشرياني عبر إفراز الرينين من الجهاز المجاور للكبيبات، ويحفز نخاع العظم على تصنيع كريات الدم الحمراء عبر هرمون الإريثروبويتين (EPO).','Regulates arterial blood pressure via juxtaglomerular renin secretion and stimulates bone marrow erythropoiesis via erythropoietin (EPO).','["ACE Inhibitors / ARBs","SGLT2 Inhibitors","Loop & Thiazide Diuretics","Potassium-Sparing Diuretics"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-nervous','الجهاز العصبي','Nervous System','Systema nervosum','مركز القيادة الكهروكيميائية المكون من الدماغ والحبل الشوكي (CNS) والأعصاب المحيطية والذاتية (PNS/ANS) المسؤول عن الإدراك والحركة والتوازن الداخلي.','Electrochemical command network comprising the brain and spinal cord (CNS) and peripheral/autonomic nerves (PNS/ANS) governing cognition, motor control, and homeostasis.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,TRUE,'يتصل بجهاز الغدد الصماء عبر المحور الوطائي-النخامي (Hypothalamic-Pituitary Axis)، وينظم ضربات القلب وحركة الأمعاء والقصبات عبر الفرعين الودي ونظير الودي.','Interfaces with the endocrine system via the hypothalamic-pituitary axis and modulates cardiac, bronchial, and gastrointestinal tone via sympathetic and parasympathetic divisions.','["Antiepileptics","Antiplatelets / Thrombolytics (Stroke)","Selective Serotonin Reuptake Inhibitors","Autonomic Cholinergic/Adrenergic Modulators"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-endocrine','جهاز الغدد الصماء','Endocrine System','Systema endocrinum','منظومة الغدد الصماء المفرزة للهرمونات مباشرة في مجرى الدم لتنظيم الاستقلاب الخلوي، توازن الجلوكوز والكالسيوم، والنمو والتكاثر.','Ductless glandular network secreting hormones into the bloodstream to regulate cellular metabolism, glucose/calcium homeostasis, and growth.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,FALSE,'يتكامل مع الجهاز العصبي المركزي في منطقة تحت المهاد، ومع الكبد والعضلات والنسيج الدهني في تنظيم حساسية الأنسولين.','Integrates with the CNS at the hypothalamus and coordinates glucose homeostasis across liver, skeletal muscle, and adipose tissue.','["Biguanides (Metformin)","GLP-1 Receptor Agonists","SGLT2 Inhibitors","Thyroid Hormone Replacements"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-skeletal','الجهاز الهيكلي العظمي','Skeletal System','Systema skeletale','الدعامة العظمية والغضروفية والمفصلية للجسم، ومخزن الكالسيوم والفوسفات، ومقر تكون خلايا الدم في نخاع العظم الأحمر.','Osseous, cartilaginous, and articular framework providing structural protection, mineral storage, and hematopoiesis within red bone marrow.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,FALSE,'يعتمد على فيتامين D النشط القادم من الكلية وهرمون جار الدرقية (PTH) للحفاظ على كثافة المعدن العظمي.','Depends on renal calcitriol activation and parathyroid hormone (PTH) to maintain bone mineral density.','["Bisphosphonates","Calcium & Vitamin D3 Analogs","DMARDs"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-muscular','الجهاز العضلي','Muscular System','Systema musculare','الأنسجة العضلية الهيكلية الإرادية والملساء والقلبية المسؤولة عن الحركة الميكانيكية، ثبات القوام، وتوليد الحرارة ومصرف الجلوكوز الرئيسي.','Skeletal, smooth, and cardiac muscle tissues governing mechanical locomotion, posture, thermogenesis, and peripheral glucose uptake.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,FALSE,'يستجيب للأستيل كولين عند الموصل العصبي العضلي (Neuromuscular Junction) ويستهلك الجزء الأكبر من الجلوكوز بتحفيز الأنسولين.','Responds to acetylcholine at the neuromuscular junction and serves as the primary site of insulin-stimulated glucose disposal.','["Neuromuscular Blockers","Skeletal Muscle Relaxants"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-immune-lymphatic','الجهاز المناعي واللمفاوي','Immune & Lymphatic System','Systema lymphoideum et immunitatis','شبكة الأوعية والعقد اللمفاوية والطحال والغدة الزعترية والخلايا المناعية الفطرية والتكيفية المسؤولة عن الدفاع ضد الممرضات وتصريف السائل الخلالي.','Lymphatic vessels, nodes, spleen, thymus, and innate/adaptive leukocytes mediating host defense and interstitial fluid return.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,FALSE,'يعيد السائل اللمفاوي إلى الدورة الوريدية الجهازية عبر القناة الصدرية وينسق الاستجابة الالتهابية في جميع الأعضاء.','Returns lymph to systemic venous circulation via the thoracic duct and coordinates inflammatory responses across all organs.','["Corticosteroids","Immunomodulators","Monoclonal Antibodies","Vaccines"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-integumentary','الجهاز اللحافي والجلد','Integumentary System','Integumentum commune','الحاجز الفيزيائي والمناعي الخارجي المكون من البشرة والأدمة والنسيج تحت الجلد والملحقات الجلدية، والمسؤول عن تنظيم الحرارة وتصنيع فيتامين D.','External barrier comprising epidermis, dermis, hypodermis, and cutaneous appendages governing thermoregulation and vitamin D synthesis.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,FALSE,'يمثل خط الدفاع الأول للجهاز المناعي، ويوفر مساراً دوائياً عبر الجلد (Transdermal Delivery) لتجاوز الاستقلاب الكبدي الأولي.','Serves as the frontline physical barrier for immunity and provides a transdermal drug delivery route bypassing first-pass hepatic metabolism.','["Topical Corticosteroids","Emollients & Barrier Repair","Topical Antimicrobials"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-reproductive','الجهاز التناسلي','Reproductive System','Systema genitale','الأعضاء التناسلية الذكرية والأنثوية المسؤولة عن تكوين الأمشاج، إفراز الهرمونات الجنسية، ودعم الحمل والتطور الجنيني.','Male and female reproductive organs governing gametogenesis, sex steroid secretion, and gestational support.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,FALSE,'يخضع لتنظيم موجهات الغدد التناسلية (FSH/LH) من الفص الأمامي للغدة النخامية ويشترك تشريحياً وجنينياً مع الجهاز البولي.','Regulated by anterior pituitary gonadotropins (FSH/LH) and shares embryological urogenital ridge origins with the urinary system.','["Hormonal Modulators","Tocolytics / Uterotonics"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-special-senses','الحواس الخاصة (العين والأذن)','Special Senses (Ophthalmic & Otic)','Organa sensuum','الأعضاء الحسية المتخصصة في الإبصار (Oculus) والسمع والتوازن الدهليزي (Auris) والشم والتذوق لتحويل المنبهات الفيزيائية والكيميائية إلى إشارات عصبية.','Specialized sensory organs for vision (Oculus), hearing and vestibular equilibrium (Auris), olfaction, and gustation.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,FALSE,'ترتبط مباشرة بالأعصاب القحفية (Cranial Nerves I, II, III, IV, VI, VII, VIII, IX) لنقل الإشارات الحسية إلى القشرة المخية.','Directly wired to cranial nerves I, II, III, IV, VI, VII, VIII, and IX to relay sensory transduction to cerebral cortices.','["Ophthalmic Prostaglandin Analogs","Ophthalmic Beta-Blockers","Vestibular Suppressants"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO body_systems(id,name_ar,name_en,latin_name,description_ar,description_en,status_code,last_human_reviewed_at,has_detailed_pathway,inter_system_relations_ar,inter_system_relations_en,related_drug_classes) VALUES('sys-hematologic','الدم وتكون الدم','Hematologic & Hematopoietic System','Systema haematopoieticum','منظومة البلازما وكريات الدم الحمراء والبيضاء والصفائح الدموية ونخاع العظم وشلال التخثر المسؤولة عن نقل الأكسجين والإرقاء الدموي.','Plasma, erythrocytes, leukocytes, platelets, bone marrow, and coagulation cascade responsible for oxygen transport and hemostasis.','EDUCATIONAL_FOUNDATION_PUBLISHED',NULL,FALSE,'يعتمد على الحديد الممتص في الاثني عشر، وفيتامين B12 بمساعدة العامل الداخلي المعدي، وإريثروبويتين الكلية لتصنيع الهيموغلوبين.','Relies on duodenal iron absorption, gastric intrinsic factor-mediated vitamin B12 uptake, and renal erythropoietin for hemoglobin synthesis.','["Oral & Parenteral Iron Preparations","Direct Oral Anticoagulants (DOACs)","Antiplatelet Agents","Erythropoiesis-Stimulating Agents"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO organs(id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code,has_3d_asset,asset_3d_id,location_ar,location_en,related_disease_ids,related_drug_classes) VALUES('organ-heart','sys-cardiovascular','القلب البشري','Human Heart','Cor','عضو عضلي أجوف رباعي الحجرات يقع في المنصف الأوسط (Mediastinum medium)، يضخ الدم المؤكسج إلى الدورة الجهازية عبر الأبهر والدم غير المؤكسج إلى الرئتين عبر الجذع الرئوي تحت قيادة نظام التوصيل الكهربائي الذاتي.','Four-chambered hollow muscular pump in the middle mediastinum driving pulmonary and systemic circulation under intrinsic sinoatrial pacemaking.','EDUCATIONAL_FOUNDATION_PUBLISHED',TRUE,'3d-cor-chambers-low-v1','المنصف الأوسط داخل جوف التامور خلف عظم القص (Mediastinum medium)','Middle mediastinum within the pericardial cavity posterior to the sternum','["dis-hypertension","dis-heart-failure","dis-coronary-artery-disease","dis-atrial-fibrillation"]','["Beta-1 Selective Blockers","ACE Inhibitors","Calcium Channel Blockers","Class III Antiarrhythmics"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO organs(id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code,has_3d_asset,asset_3d_id,location_ar,location_en,related_disease_ids,related_drug_classes) VALUES('organ-blood-vessels','sys-cardiovascular','الشجرة الوعائية الشريانية والوريدية','Arterial, Capillary & Venous Vasculature','Vasa sanguinea (Arteriae, Vasa capillaria, Venae)','شبكة الأوعية المرنة والعضلية والشرينات المقاومة والشعيرات التبادلية والأوردة السعوية التي تضبط المقاومة الوعائية الجهازية (SVR).','Elastic arteries, resistance arterioles, exchange capillaries, and capacitance veins governing systemic vascular resistance (SVR).','EDUCATIONAL_FOUNDATION_PUBLISHED',FALSE,NULL,'موزعة في جميع أنحاء الجسم بدءاً من الأبهر وحتى الوريدين الأجوفين','Systemic distribution from aortic root to venae cavae','["dis-hypertension","dis-coronary-artery-disease","dis-ischemic-stroke","dis-dvt"]','["Calcium Channel Blockers","ACE Inhibitors","Nitrates","Statins","Anticoagulants"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO organs(id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code,has_3d_asset,asset_3d_id,location_ar,location_en,related_disease_ids,related_drug_classes) VALUES('organ-lungs','sys-respiratory','الرئتان والشجرة القصبية','Lungs & Bronchial Tree','Pulmones et Arbor bronchialis','عضوا التبادل الغازي في التجويف الصدري، يضمان نحو 300-500 مليون سنخ رئوي (Alveoli pulmonis) محاطة بشبكة شعرية كثيفة لانتشار الأكسجين وثاني أكسيد الكربون.','Paired thoracic organs housing 300-500 million alveoli surrounded by pulmonary capillary beds for gas diffusion.','EDUCATIONAL_FOUNDATION_PUBLISHED',FALSE,'3d-pulmones-bronchi-v1','التجويف الصدري على جانبي المنصف داخل الجوف الجنبي (Cavitas pleuralis)','Thoracic cavity flanking the mediastinum within the pleural cavities','["dis-bronchial-asthma","dis-copd","dis-pneumonia"]','["Beta-2 Agonists","Inhaled Corticosteroids","Muscarinic Antagonists"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO organs(id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code,has_3d_asset,asset_3d_id,location_ar,location_en,related_disease_ids,related_drug_classes) VALUES('organ-kidneys','sys-renal','الكليتان والوحدات الأنبوبية (النفرونات)','Kidneys & Nephrons','Renes (Nephrona)','عضوان خلف الصفاق يحتوي كل منهما على نحو مليون وحدة كلوية (Nephron) تؤدي الترشيح الكبيبي وإعادة الامتصاص والإفراز الأنبوبي وتنظم إطراح الأدوية المائية.','Paired retroperitoneal organs each containing ~1 million nephrons executing glomerular filtration, tubular transport, and hydrophilic drug clearance.','EDUCATIONAL_FOUNDATION_PUBLISHED',FALSE,'3d-ren-nephron-v1','الحيز خلف الصفاق بين الفقرة الصدرية T12 والقطنية L3 (Retroperitoneum)','Retroperitoneal space spanning T12 to L3 vertebrae','["dis-ckd","dis-aki","dis-nephrolithiasis","dis-hypertension"]','["Loop Diuretics","Thiazide Diuretics","SGLT2 Inhibitors","ACE Inhibitors / ARBs"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO organs(id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code,has_3d_asset,asset_3d_id,location_ar,location_en,related_disease_ids,related_drug_classes) VALUES('organ-liver','sys-digestive','الكبد والجهاز الصفراوي','Liver & Biliary Tree','Hepar et Viae biliares','أكبر غدة استقلابية في الجسم؛ يستقبل التروية المزدوجة من الوريد البابي والشريان الكبدي، ويضم إنزيمات السيتوكروم (CYP450) المسؤولة عن استقلاب الطور الأول والثاني للأدوية.','Largest metabolic gland receiving dual portal/arterial blood supply and housing CYP450 enzymes for Phase I and Phase II drug biotransformation.','EDUCATIONAL_FOUNDATION_PUBLISHED',FALSE,NULL,'الربع العلوي الأيمن من التجويف البطني تحت الحجاب الحاجز (Regio hypochondriaca dextra)','Right upper quadrant of the abdominal cavity beneath the diaphragm','["dis-nafld-masld"]','["Statins","CYP450 Substrates/Inhibitors","Bile Acid Sequestrants"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO organs(id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code,has_3d_asset,asset_3d_id,location_ar,location_en,related_disease_ids,related_drug_classes) VALUES('organ-stomach-duodenum','sys-digestive','المعدة والاثنا عشر','Stomach & Duodenum','Gaster (Ventriculus) et Duodenum','موضع الهضم الحمضي والإنزيمي الأولي وتنظيم إفراز حمض الهيدروكلوريك عبر مضخة البروتون (H+/K+ ATPase) في الخلايا الجدارية وبداية الامتصاص الدوائي.','Site of acid-peptic digestion via parietal cell H+/K+ ATPase proton pumps and proximal intestinal nutrient/drug absorption.','EDUCATIONAL_FOUNDATION_PUBLISHED',FALSE,NULL,'المنطقة الشرسوفية والربع العلوي الأيسر من البطن (Regio epigastrica)','Epigastric and left hypochondriac abdominal regions','["dis-gerd","dis-peptic-ulcer"]','["Proton Pump Inhibitors (PPIs)","H2 Receptor Antagonists","Antacids"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO organs(id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code,has_3d_asset,asset_3d_id,location_ar,location_en,related_disease_ids,related_drug_classes) VALUES('organ-brain','sys-nervous','الدماغ البشري والحاجز الدموي الدماغي','Human Brain & Blood-Brain Barrier','Encephalon (Cerebrum, Cerebellum, Truncus encephali)','يتألف من المخ والمخيخ وجذع الدماغ، ويحميه الحاجز الدموي الدماغي (Blood-Brain Barrier) المزود بوصلات محكمة ومضخات تدفق (P-glycoprotein) تنظم عبور الأدوية العصبية.','Comprises the cerebrum, cerebellum, and brainstem protected by the tight-junction Blood-Brain Barrier (BBB) and P-glycoprotein efflux transporters.','EDUCATIONAL_FOUNDATION_PUBLISHED',FALSE,NULL,'التجويف القحفي داخل الجمجمة (Cavitas cranii)','Cranial cavity enclosed by the neurocranium and meninges','["dis-ischemic-stroke"]','["Antiplatelets","Antiepileptics","CNS-Penetrant Analgesics"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO organs(id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code,has_3d_asset,asset_3d_id,location_ar,location_en,related_disease_ids,related_drug_classes) VALUES('organ-pancreas-islets','sys-endocrine','البنكرياس وجزر لانغرهانس','Pancreas & Islets of Langerhans','Pancreas (Insulae pancreaticae)','غدة مختلطة صماء وخارجية الإفراز؛ تفرز خلايا بيتا فيها الأنسولين وتفرز خلايا ألفا الغلوكاغون لضبط مستويات الجلوكوز في الدم.','Mixed exocrine and endocrine gland whose pancreatic islets secrete insulin (beta cells) and glucagon (alpha cells).','EDUCATIONAL_FOUNDATION_PUBLISHED',FALSE,NULL,'الحيز خلف الصفاق ممتداً من عروة الاثني عشر إلى سرة الطحال','Retroperitoneal space extending from the duodenal C-loop to the splenic hilum','["dis-type2-diabetes"]','["Biguanides (Metformin)","GLP-1 Receptor Agonists","SGLT2 Inhibitors","Insulins"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO organs(id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code,has_3d_asset,asset_3d_id,location_ar,location_en,related_disease_ids,related_drug_classes) VALUES('organ-thyroid','sys-endocrine','الغدة الدرقية','Thyroid Gland','Glandula thyroidea','غدة صماء تقع في مقدم العنق أمام الرغامى، تفرز هرموني الثيروكسين (T4) وثلاثي يودوثيرونين (T3) لضبط معدل الاستقلاب الأساسي للجسم.','Anterior cervical endocrine gland secreting thyroxine (T4) and triiodothyronine (T3) to regulate basal metabolic rate.','EDUCATIONAL_FOUNDATION_PUBLISHED',FALSE,NULL,'مقدم العنق أمام الحلقات الرغامية الثانية إلى الرابعة','Anterior neck overlying tracheal rings C5-T1','["dis-hypothyroidism"]','["Thyroid Hormone Replacements (Levothyroxine)","Thionamides"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO organs(id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code,has_3d_asset,asset_3d_id,location_ar,location_en,related_disease_ids,related_drug_classes) VALUES('organ-bone-marrow','sys-hematologic','نخاع العظم الأحمر وتكون الدم','Red Bone Marrow & Hematopoietic Niche','Medulla ossium rubra','النسيج المكون للدم داخل العظام المسطحة ونهايات العظام الطويلة، المسؤول عن إنتاج كريات الدم الحمراء والبيضاء والصفائح الدموية.','Hematopoietic tissue within axial bones and proximal epiphyses producing erythrocytes, leukocytes, and platelets.','EDUCATIONAL_FOUNDATION_PUBLISHED',FALSE,NULL,'النسيج الإسفنجي لعظام الحوض والقص والفقرات والأضلاع','Trabecular cavities of pelvis, sternum, vertebrae, and ribs','["dis-iron-deficiency-anemia"]','["Iron Preparations","Vitamin B12 & Folic Acid","Erythropoietin Analogs"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-hypertension','sys-cardiovascular','BA00','فرط ضغط الدم الشرياني الأساسي','Essential Systemic Arterial Hypertension','ارتفاع مستدام في ضغط الدم الشرياني الجهازي نتيجة زيادة المقاومة الوعائية المحيطية و/أو النتاج القلبي وتنشيط محور الرينين-أنجيوتنسين-ألدوستيرون (RAAS).','Sustained elevation of systemic arterial blood pressure driven by increased systemic vascular resistance, endothelial dysfunction, and RAAS activation.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-heart-failure','sys-cardiovascular','BD10','قصور القلب المزمن (انخفاض أو حفظ كسر القذف)','Chronic Heart Failure (HFrEF & HFpEF)','متلازمة سريرية تنتج عن خلل بنيوي أو وظيفي في امتلاء البطينين أو قذف الدم، مما يعجز عن تلبية الاحتياجات الاستقلابية للأنسجة أو يلبيها على حساب ارتفاع ضغوط الامتلاء.','Clinical syndrome caused by structural or functional impairment of ventricular filling or ejection of blood, leading to systemic hypoperfusion and pulmonary/venous congestion.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-coronary-artery-disease','sys-cardiovascular','BA80','داء الشرايين التاجية الإقفاري (الذبحة الصدرية)','Coronary Artery Disease & Ischemic Heart Disease','عدم توازن بين إمداد عضلة القلب بالأكسجين عبر الشرايين التاجية والطلب الاستقلابي لعضلة القلب، غالباً بسبب اللويحات العصيدية التاجية.','Mismatch between myocardial oxygen supply and demand typically caused by atherosclerotic narrowing of epicardial coronary arteries.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-atrial-fibrillation','sys-cardiovascular','BC81.3','الرجفان الأذيني','Atrial Fibrillation (AF)','اضطراب النظم القلبي فوق البطيني الأكثر شيوعاً، يتميز بتفريغ كهربائي أذيني فوضوي سريع يفقد الأذينين انقباضهما المتزامن ويزيد خطر الخثرات الصمية.','Most common sustained supraventricular tachyarrhythmia characterized by chaotic atrial electrical activation, loss of atrial kick, and thromboembolic stroke risk.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-bronchial-asthma','sys-respiratory','CA23','الربو القصبي','Bronchial Asthma','مرض التهابي مزمن في الطرق الهوائية يتميز بفرط الاستجابة القصبية وتضيق القصبات القابل للعكس جزئياً أو كلياً.','Chronic inflammatory airway disorder characterized by bronchial hyperresponsiveness and variable, reversible airflow limitation.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-copd','sys-respiratory','CA22','الداء الرئوي الانسدادي المزمن (COPD)','Chronic Obstructive Pulmonary Disease (COPD)','مرض رئوي مزمن مترقٍ يتميز بتحدد مستديم في جريان الهواء نتيجة التهاب القصيبات المزمن وتدمير الجدران السنخية (النفاخ الرئوي).','Preventable, treatable lung disease characterized by persistent respiratory symptoms and fixed airflow limitation due to airway and alveolar abnormalities.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-pneumonia','sys-respiratory','CA40','ذات الرئة المكتسبة من المجتمع (Pneumonia)','Community-Acquired Pneumonia (CAP)','خمج حاد في النسيج البرنشيمي الرئوي يصيب الأسناخ الرئوية ويؤدي لامتلائها بالنضح الالتهابي والخلايا المناعية مما يعيق تبادل الغازات.','Acute infection of the pulmonary parenchyma causing alveolar inflammatory exudation, consolidation, and impaired oxygenation.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-gerd','sys-digestive','DA22','داء الارتجاع المعدي المريئي (GERD)','Gastroesophageal Reflux Disease (GERD)','ارتجاع محتويات المعدة الحمضية أو الصفراوية إلى المريء نتيجة ارتخاء عابر أو ضعف في المصرة المريئية السفلية (LES).','Retrograde flow of gastric contents into the esophagus causing troublesome symptoms or mucosal injury due to lower esophageal sphincter incompetence.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-peptic-ulcer','sys-digestive','DA60','داء القرحة الهضمية (المعدية والعفجية)','Peptic Ulcer Disease (Gastric & Duodenal)','تفرق اتصال في الغشاء المخاطي للمعدة أو الاثني عشر يمتد عبر الطبقة العضلية للمخاطية نتيجة اختلال التوازن بين العوامل العدوانية وآليات الدفاع المخاطية.','Mucosal defect in the stomach or duodenum penetrating through the muscularis mucosae due to acid-peptic injury overcoming mucosal defense.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-nafld-masld','sys-digestive','DB92','المرض الكبدي الدهني المرتبط بالخلل الاستقلابي (MASLD / NAFLD)','Metabolic Dysfunction-Associated Steatotic Liver Disease (MASLD)','تراكم الشحوم الثلاثية داخل أكثر من 5% من الخلايا الكبدية بغياب الأسباب الثانوية، ويرتبط وثيقاً بمقاومة الأنسولين والمتلازمة الاستقلابية.','Hepatic steatosis (>5% hepatocytes) associated with insulin resistance and cardiometabolic risk factors in the absence of secondary causes.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-ckd','sys-renal','GB61','المرض الكلوي المزمن (CKD)','Chronic Kidney Disease (CKD)','شذوذ بنيوي أو وظيفي في الكلية يستمر لأكثر من 3 أشهر مع انخفاض معدل الترشيح الكبيبي (eGFR < 60 mL/min/1.73m²) و/أو بيلة ألبومينية.','Persistent abnormality of kidney structure or function for >3 months, defined by eGFR <60 mL/min/1.73m² and/or albuminuria.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-aki','sys-renal','GB60','الأذية الكلوية الحادة (AKI)','Acute Kidney Injury (AKI)','تدهور حاد وسريع (خلال ساعات إلى أيام) في الوظيفة الكلوية يؤدي لارتفاع كرياتينين المصل و/أو شح البول واضطراب توازن السوائل والشوارد.','Abrupt decline in renal filtration function over hours to days resulting in azotemia, fluid retention, and electrolyte derangements.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-nephrolithiasis','sys-renal','GB70','الحصيات الكلوية والبولية (Nephrolithiasis)','Nephrolithiasis & Urolithiasis','تشكل بلورات معدنية صلبة (أوكسالات الكالسيوم، حمض اليوريك، وغيرها) في الكؤوس والحويضة الكلوية قد تنتقل للحالب مسببة القولنج الكلوي.','Formation of crystalline mineral calculi within the renal pelvis or calyces capable of obstructing the ureter and causing acute renal colic.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-ischemic-stroke','sys-nervous','8B11','السكتة الدماغية الإقفارية الحادة','Acute Ischemic Stroke','عجز عصبي بؤري مفاجئ ينجم عن انسداد وعائي شرياني دماغي (خثري أو صمي) يؤدي إلى إقفار واحتشاء النسيج العصبي.','Sudden focal neurological deficit caused by thrombotic or cardioembolic occlusion of a cerebral artery resulting in cerebral infarction.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-type2-diabetes','sys-endocrine','5A11','داء السكري من النمط الثاني','Type 2 Diabetes Mellitus (T2DM)','اضطراب استقلابي مزمن يتميز بارتفاع سكر الدم المزمن الناتج عن مقاومة الأنسجة المحيطية للأنسولين مع قصور تدريجي في إفراز الأنسولين من خلايا بيتا البنكرياسية.','Chronic metabolic disorder characterized by hyperglycemia resulting from peripheral insulin resistance and progressive pancreatic beta-cell secretory dysfunction.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-hypothyroidism','sys-endocrine','5A00','قصور الغدة الدرقية الأولي','Primary Hypothyroidism','نقص إفراز هرموني الغدة الدرقية (T4 و T3) مما يؤدي إلى تباطؤ شامل في عمليات الاستقلاب الخلوي وتوليد الطاقة في مختلف أجهزة الجسم.','Deficiency of thyroid hormones (T4 and T3) resulting in generalized slowing of cellular metabolic processes across organ systems.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-iron-deficiency-anemia','sys-hematologic','3A00','فقر الدم بعوز الحديد','Iron Deficiency Anemia (IDA)','أشيع أنماط فقر الدم عالمياً، يتميز بنقص مخازن الحديد في الجسم مما يضعف تصنيع الهيم في أرومات الحمر بنخاع العظم وينتج كريات حمراء صغيرة الحجم ناقصة الصباغ.','Most prevalent anemia worldwide caused by depleted body iron stores impairing heme synthesis and producing microcytic, hypochromic erythrocytes.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO diseases(id,primary_system_id,icd11_code,name_ar,name_en,introduction_ar,introduction_en,status_code) VALUES('dis-dvt','sys-hematologic','BD71','الخثار الوريدي العميق والانصمام الخثري الوريدي (DVT / VTE)','Deep Vein Thrombosis & Venous Thromboembolism (VTE)','تشكل خثرة غنية بالفيبرين والكريات الحمر داخل الأوردة العميقة (غالباً في الطرف السفلي) وفق ثلاثية فيرخوف، مع خطر انتقالها للرئة.','Formation of a fibrin-rich thrombus within deep veins (most commonly lower extremity) driven by Virchow triad, carrying risk of pulmonary embolism.','DRAFT') ON CONFLICT (id) DO NOTHING;
INSERT INTO active_ingredients(id,name_ar,name_en,class_name,general_description_ar,general_description_en,safety_note,status_code,last_human_reviewed_at) VALUES('ing-bisoprolol','بيسوبرولول','Bisoprolol','Selective Beta-1 Adrenergic Receptor Blocker','حاصر انتقائي لمستقبلات بيتا-1 الأدرينالية في عضلة القلب ونظام التوصيل (SA/AV Nodes)؛ يقلل سرعة القلب والقلوصية واستهلاك الأكسجين وإفراز الرينين الكلوي.','Cardioselective beta-1 adrenergic antagonist reducing SA nodal automaticity, AV nodal conduction velocity, myocardial oxygen demand, and juxtaglomerular renin release.','معلومات دوائية تعليمية فقط — لا يُتوقف عن حاصرات بيتا فجأة لتجنب تسرع القلب الارتدادي، ولا تُحدد الجرعات إلا بوصفة طبية.','DRAFT',NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO active_ingredients(id,name_ar,name_en,class_name,general_description_ar,general_description_en,safety_note,status_code,last_human_reviewed_at) VALUES('ing-lisinopril','ليزينوبريل','Lisinopril','Angiotensin-Converting Enzyme (ACE) Inhibitor','مثبط للإنزيم المحول للأنجيوتنسين؛ يمنع تحويل أنجيوتنسين I إلى أنجيوتنسين II المضيق للأوعية ويقلل تدرك البراديكينين الموسع للأوعية ويخفض الضغط داخل الكبيبة الكلوية.','ACE inhibitor blocking conversion of Angiotensin I to Angiotensin II and reducing bradykinin degradation, lowering systemic afterload and intraglomerular pressure.','معلومات تعليمية فقط — يمنع استخدامه أثناء الحمل ويستلزم مراقبة البوتاسيوم ووظيفة الكلية بإشراف الطبيب.','DRAFT',NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO active_ingredients(id,name_ar,name_en,class_name,general_description_ar,general_description_en,safety_note,status_code,last_human_reviewed_at) VALUES('ing-amlodipine','أملوديبين','Amlodipine','Dihydropyridine Calcium Channel Blocker (L-Type)','حاصر لقنوات الكالسيوم من النمط L في العضلات الملساء الوعائية؛ يسبب توسع الشرينات المحيطية والشرايين التاجية وخفض المقاومة الوعائية الجهازية.','Dihydropyridine L-type calcium channel blocker selectively relaxing arterial smooth muscle to lower peripheral vascular resistance.','معلومات تعليمية فقط — قد يسبب وذمة محيطية في الكاحلين نتيجة توسع الشرينات قبل الشعرية.','DRAFT',NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO active_ingredients(id,name_ar,name_en,class_name,general_description_ar,general_description_en,safety_note,status_code,last_human_reviewed_at) VALUES('ing-furosemide','فوروسيميد','Furosemide','Loop Diuretic (NKCC2 Symporter Inhibitor)','مدر عروة يثبط الناقل المشترك (Na+-K+-2Cl-) في الطرف الصاعد السميك لعروة هنلي في النفرون الكلوي، مما يزيد إطراح الصوديوم والماء لتخفيف الاحتقان الرئوي والمحيطي.','Loop diuretic inhibiting the luminal Na+-K+-2Cl- cotransporter (NKCC2) in the thick ascending limb of the loop of Henle.','معلومات تعليمية فقط — يستلزم مراقبة شوارد الدم (البوتاسيوم والمغنيسيوم) ووظيفة الكلية تحت إشراف طبي.','DRAFT',NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO active_ingredients(id,name_ar,name_en,class_name,general_description_ar,general_description_en,safety_note,status_code,last_human_reviewed_at) VALUES('ing-salbutamol','سالبوتامول (ألبوتيرول)','Salbutamol (Albuterol)','Short-Acting Beta-2 Adrenergic Agonist (SABA)','شاد انتقائي لمستقبلات بيتا-2 في العضلات الملساء القصبية؛ ينشط إنزيم الأدينيلات سيكلاز ويرفع الـ cAMP الخلوي مما يؤدي لارتخاء سريع في التشنج القصبي.','Selective beta-2 adrenergic receptor agonist increasing intracellular cAMP to induce rapid bronchial smooth muscle relaxation.','معلومات تعليمية فقط — الاعتماد المفرط على موسعات القصبات الإسعافية دون علاج الالتهاب الأساسي يستوجب مراجعة الطبيب.','DRAFT',NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO active_ingredients(id,name_ar,name_en,class_name,general_description_ar,general_description_en,safety_note,status_code,last_human_reviewed_at) VALUES('ing-omeprazole','أوميبرازول','Omeprazole','Proton Pump Inhibitor (H+/K+ ATPase Inhibitor)','طليعة دواء تتفعل في الوسط الحمضي لقنيات الخلايا الجدارية المعدية وترتبط تساهمياً بمضخة البروتون (H+/K+ ATPase) لتثبيط الخطوة النهائية لإفراز حمض المعدة.','Substituted benzimidazole prodrug irreversibly inhibiting the gastric parietal cell H+/K+ ATPase proton pump.','معلومات تعليمية فقط — يُنصح بمراجعة التداخلات الدوائية (مثل CYP2C19) مع الصيدلاني أو الطبيب.','DRAFT',NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO active_ingredients(id,name_ar,name_en,class_name,general_description_ar,general_description_en,safety_note,status_code,last_human_reviewed_at) VALUES('ing-metformin','ميتفورمين','Metformin','Biguanide Antihyperglycemic Agent','ينشط إنزيم AMPK الكبدي ليقلل استحداث السكر الكبدي (Gluconeogenesis) ويحسن حساسية الأنسجة المحيطية للأنسولين دون تحفيز مباشر لإفراز الأنسولين.','Activates hepatic AMP-activated protein kinase (AMPK), suppressing hepatic gluconeogenesis and enhancing peripheral insulin sensitivity.','معلومات تعليمية فقط — تتطلب وظيفة الكلية (eGFR) تقييماً دورياً لتجنب تراكم الدواء.','DRAFT',NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO active_ingredients(id,name_ar,name_en,class_name,general_description_ar,general_description_en,safety_note,status_code,last_human_reviewed_at) VALUES('ing-dapagliflozin','داباغليفلوزين','Dapagliflozin','Sodium-Glucose Cotransporter-2 (SGLT2) Inhibitor','يثبط ناقل SGLT2 في الأنبوب الملتوي القريب للنفرون الكلوي، مما يزيد طرح الجلوكوز والصوديوم في البول ويعيد التلقيم الراجع الأنبوبي الكبيبي لحماية الكلية والقلب.','Selectively inhibits SGLT2 in the proximal renal tubule, promoting glucosuria/natriuresis and restoring tubuloglomerular feedback.','معلومات تعليمية فقط — يُصرف ويُتابع بإشراف الطبيب المختص.','DRAFT',NULL) ON CONFLICT (id) DO NOTHING;
